static const int XGB_ROOTS[220] = {0, 23, 42, 67, 88, 113, 138, 161, 180, 205, 234, 261, 292, 315, 334, 357, 384, 405, 428, 451, 474, 501, 528, 549, 568, 597, 626, 647, 666, 693, 714, 739, 768, 795, 816, 839, 864, 883, 908, 931, 958, 981, 1006, 1025, 1044, 1063, 1086, 1113, 1130, 1155, 1178, 1207, 1226, 1241, 1266, 1285, 1312, 1335, 1356, 1375, 1394, 1415, 1438, 1459, 1482, 1505, 1524, 1547, 1560, 1587, 1606, 1625, 1650, 1671, 1696, 1711, 1732, 1751, 1772, 1793, 1812, 1835, 1850, 1863, 1886, 1909, 1924, 1937, 1948, 1975, 2000, 2019, 2040, 2059, 2078, 2089, 2104, 2119, 2146, 2171, 2190, 2213, 2236, 2249, 2262, 2283, 2300, 2315, 2336, 2367, 2378, 2391, 2404, 2417, 2436, 2449, 2468, 2489, 2514, 2537, 2552, 2573, 2584, 2609, 2632, 2645, 2668, 2681, 2704, 2721, 2732, 2751, 2766, 2783, 2796, 2813, 2834, 2857, 2868, 2879, 2896, 2923, 2944, 2961, 2990, 3015, 3036, 3063, 3086, 3097, 3124, 3139, 3150, 3179, 3192, 3205, 3226, 3239, 3264, 3277, 3288, 3303, 3314, 3329, 3342, 3359, 3370, 3387, 3404, 3417, 3446, 3469, 3494, 3513, 3528, 3543, 3554, 3581, 3612, 3637, 3654, 3671, 3688, 3709, 3732, 3753, 3776, 3799, 3818, 3847, 3878, 3889, 3908, 3939, 3968, 3997, 4012, 4029, 4044, 4063, 4088, 4105, 4124, 4149, 4174, 4187, 4202, 4229, 4248, 4265, 4288, 4315, 4334, 4351, 4362, 4375, 4394, 4423, 4436, 4449};
static const int XGB_TREE_COUNT = 220;
static const double XGB_BASE_MARGIN = 0.39999995791051124;

int milk_xgb_score(const double input[3], double output[2]) {
    if (input == NULL || output == NULL) return -1;
    for (int i = 0; i < 3; ++i) if (!isfinite(input[i])) return -2;
    double margin = XGB_BASE_MARGIN;
    for (int t = 0; t < XGB_TREE_COUNT; ++t) {
        int node = XGB_ROOTS[t];
        while (XGB_NODES[node].feature >= 0) {
            const XgbNode *n = &XGB_NODES[node];
            node = ((float)input[n->feature] < (float)n->threshold) ? n->left : n->right;
        }
        margin += XGB_NODES[node].value;
    }
    double p = 1.0 / (1.0 + exp(-margin));
    output[0] = 1.0 - p;
    output[1] = p;
    return 0;
}
